fn reverse(s: Vec<i8>) -> Vec<i8> {
    let mut rev = Vec::with_capacity(s.len()); // Create a new vector with the same capacity as the input
    for &item in s.iter().rev() { // Iterate over the input vector in reverse order
        rev.push(item); // Push each item into the new vector
    }
    rev // Return the reversed vector
}